// apply-gambar.mjs — Pasang GAMBAR dari server lama.
//   (1) copy-gambar.bat  → skrip salin AMAN (whitelist: hanya *.jpg/*.png/*.gif;
//       .exe/.scr/.pif TIDAK akan ikut tersalin). Edit variabel SRC di dalamnya.
//   (2) <img> di dalam artikel/capability/berita TIDAK lagi dibuang — sekarang
//       dialihkan dari server mati (http://dittek/..., http://10.1.x/...)
//       ke berkas lokal /gambar/uploads/<file>.
//   (3) Foto pejabat tampil di halaman Organisasi (static/gambar/org/).
//   (4) Gambar headline tampil di Berita Utama (static/gambar/artikel/).
//   (5) Foto Sekilas Dittek → static/gambar/sekilas/.
// PRASYARAT: jalankan SETELAH apply-dinamis..apply-halaman5 (script 1 s/d 9).
//
// Cara pakai (dari root project):
//     node apply-gambar.mjs
//     ...lalu edit SRC di copy-gambar.bat, jalankan:  copy-gambar.bat
//     npm run dev
// Aman dijalankan berkali-kali.

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const FILES = [
  ["copy-gambar.bat", ''],
  ["src/lib/utils.ts", ''],
  ["src/lib/types/content.ts", ''],
  ["src/lib/server/portal/transform.ts", ''],
  ["src/lib/server/portal/queries.ts", ''],
  ["src/routes/organisasi/+page.svelte", ''],
  ["src/routes/berita-utama/+page.svelte", ''],
  ["src/routes/sekilas-dittek/+page.svelte", ''],
];

let ok = 0;
for (const [path, b64] of FILES) {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, Buffer.from(b64, 'base64'));
    console.log('  ditulis:', path);
    ok++;
  } catch (e) {
    console.error('  GAGAL  :', path, '-', e.message);
  }
}

// Siapkan folder tujuan gambar.
for (const d of ['sekilas','org','artikel','umum','uploads','gallery']) {
  mkdirSync('static/gambar/' + d, { recursive: true });
}
console.log('  dibuat  : static/gambar/{sekilas,org,artikel,umum,uploads,gallery}/');

console.log('\nSelesai. ' + ok + '/' + FILES.length + ' file ditulis.');
console.log('\nLANGKAH BERIKUTNYA:');
console.log('  1) Buka copy-gambar.bat, ubah baris:  set "SRC=\\\\SERVER\\portaldittek"');
console.log('     → arahkan ke folder portal lama di server.');
console.log('  2) Jalankan: copy-gambar.bat   (hanya MEMBACA dari server, aman)');
console.log('  3) npm run dev  → cek /organisasi, /berita-utama, /sekilas-dittek, /capability');
console.log('\nCatatan: copy-gambar.bat memakai whitelist ekstensi gambar, jadi');
console.log('malware (.exe/.scr/.pif) di server TIDAK mungkin ikut tersalin.');
console.log('Folder js/ dan menu/ sengaja TIDAK disalin (itu kode, tidak dibutuhkan).');
